INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 0 FROM countries WHERE code = 'KE';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Format & transmission model', '[["Invoice generation", "Through a KRA-controlled eTIMS channel (portal, app, USSD, or OSCU/VSCU system integration) -- not free-form ERP output"], ["Transmission", "Real-time or near-real-time to KRA at issuance (KRA''s own description)"], ["Mandatory content", "Seller PIN; buyer PIN (where the buyer claims the expense/input tax); serial number; date and time of issuance and supply; item code, description, quantity, unit; tax rate; totals; unique system and invoice identifiers; QR code"], ["Verification", "QR code lets any customer verify invoice validity against KRA"]]', 'Public sources conflict on the exact wire format (structured XML per one industry briefing vs a JSON REST API per integrator documentation) -- this page deliberately does not commit to either. What is confirmed is the KRA-controlled generation channel and at-issuance transmission.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 1 FROM countries WHERE code = 'KE';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Solution channels (all free from KRA)', '[["eTIMS Online Portal", "etims.kra.go.ke -- service businesses issuing <= 10 invoices/month"], ["eTIMS Client", "Windows/Android software for goods and mixed businesses; supports multiple branches and tills"], ["eTIMS Lite", "For non-VAT taxpayers: web via eCitizen, mobile app, or USSD *222# (no internet needed)"], ["System integration", "OSCU (KRA-hosted, online systems) or VSCU (client-hosted, high-volume) via API; sandbox at etims-sbx.kra.go.ke"], ["Reverse invoicing", "Buyer-initiated invoicing for purchases from small suppliers (<= KES 5m turnover)"]]', 'Since February 2025 onboarding is fully self-service and a business may run multiple solutions simultaneously (KRA press release). The software is free; third-party integrator fees may apply.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'scope_transmission', 0 FROM countries WHERE code = 'KE';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Who must comply', '[["All businesses (since 1 Sep 2023)", "Every person carrying on business -- companies, partnerships, sole proprietors, incl. rental-income, turnover-tax and income-tax-only payers (TPA s.23A, Finance Act 2023)"], ["VAT-registered businesses", "Under mandate since 30 Nov 2022 (TIMS); only e-invoices support input VAT claims since 1 Jun 2023"], ["Small suppliers (<= KES 5m turnover)", "No direct onboarding duty -- business buyers must self-issue reverse invoices instead (mandatory since 27 Dec 2024)"], ["Excluded transactions", "Emoluments, imports, interest, airline passenger ticketing, final-withholding-tax payments, supplies by non-residents without a Kenyan PE"], ["Non-resident digital suppliers", "Exempt from the eTIMS system itself but must still issue invoices showing value and tax"]]', NULL, NULL);
INSERT INTO deep_dive_lifecycle_cards (country_id, section, sort_order, display_style) SELECT id, 'scope_transmission', 1, 'pills' FROM countries WHERE code = 'KE';
INSERT INTO deep_dive_lifecycle_card_translations (card_id, lang, title, intro_text, outro_text) VALUES ((SELECT MAX(id) FROM deep_dive_lifecycle_cards), 'en', 'The invoice flow', 'A compliant Kenyan e-invoice moves through this sequence:', 'Offline resilience is built in: eTIMS Client and VSCU keep invoicing through connectivity loss and transmit on reconnection; a system failure must be notified to KRA in writing within 24 hours.');
