INSERT INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) VALUES ((SELECT MAX(id) FROM deep_dive_lifecycle_statuses_v2), 'en', 'From 1 Jan 2026: income tax returns are validated against eTIMS sales/purchase data, withholding records and customs imports');
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'penalties_related', 0 FROM countries WHERE code = 'KE';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Statutory penalties', '[["Non-compliance with the e-invoicing obligation", "Penalty of two times the tax due (Finance Act 2023)"], ["Failure to integrate with KRA''s data system when required (> KES 5m turnover)", "Up to KES 100,000 per month (Tax Laws (Amendment) Act 2024)"], ["System failure handling", "Written notice to KRA within 24 hours; sales recorded by prescribed alternate means (Regulations 2024)"]]', 'The statutory section for the 2x-tax-due penalty is commonly cited as TPA s.86 but was not verified against the consolidated statute text in this research round -- the penalty amount itself is confirmed via Big-4 analysis of the Finance Act 2023.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'penalties_related', 1 FROM countries WHERE code = 'KE';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'The financial enforcement web', '[["Income tax deductions", "Expenses without an eTIMS-generated invoice are non-deductible (ITA s.16(1)(c), since 1 Jan 2024)"], ["Input VAT", "Only electronic tax invoices support input VAT claims and refunds (enforced since 1 Jun 2023)"], ["Tax Compliance Certificates", "Withheld from non-compliant taxpayers -- a practical bar on tenders and banking relationships"], ["Return validation (since 1 Jan 2026)", "KRA takes the higher of declared vs eTIMS income, and the lower of declared vs eTIMS expenses -- unsupported amounts face administrative disallowance at filing"]]', NULL, NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'penalties_related', 2 FROM countries WHERE code = 'KE';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', '🔍 What we could not confirm', '[["Finance Act 2026 penalty softening", "A reported change from 2x tax due to 5% of tax due (min KES 100,000 company / KES 10,000 individual) traces to a single law-firm analysis -- treat as plausible, not confirmed"], ["Exact wire format", "XML vs JSON API -- sources conflict; unresolved"], ["Pre-filled VAT returns mandate date", "The claimed 1 Jan 2025 mandatory date is secondary-sourced only (KRA''s 162,000-user figure for the automated return is confirmed, the mandate date is not)"], ["Archiving period", "A 5-year digital retention period is industry-cited but no KRA page confirming it was found this round"]]', 'Items here are excluded from the milestone timeline and summary above under this site''s sourcing standard -- listed so you know what to double-check rather than silently omitted.', NULL);
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 0 FROM countries WHERE code = 'KE';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Register on eTIMS', 'Sign up at etims.kra.go.ke using your KRA PIN (iTax credentials). Small/non-VAT taxpayers can instead use eTIMS Lite via eCitizen on the web, the mobile app, or USSD *222# with no internet connection.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 1 FROM countries WHERE code = 'KE';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Choose your solution and submit the service request', 'Select the channel that fits your business (portal, eTIMS Client, Lite, or system integration) and submit the service request with the signed commitment form and a copy of the director''s or owner''s ID. Onboarding has been fully self-service since February 2025, and you may run multiple solutions at once.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 2 FROM countries WHERE code = 'KE';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Integrating? Test on the sandbox first', 'System-to-system integrations (OSCU for KRA-hosted, VSCU for client-hosted high-volume) must be tested against the sandbox at etims-sbx.kra.go.ke before production approval, which is confirmed by SMS.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 3 FROM countries WHERE code = 'KE';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Get the data details right', 'Configure invoice layouts for the mandatory content -- especially the buyer''s PIN on any invoice the buyer will use for a deduction or input-tax claim -- and set up buyer-initiated invoicing for purchases from small suppliers. Train sales and AP/AR staff: a missing PIN now costs your customer real money.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 4 FROM countries WHERE code = 'KE';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Reconcile before you file', 'Since 1 January 2026 KRA validates returns against eTIMS data automatically. Reconcile your books against eTIMS sales and purchase records through the year -- and chase suppliers for compliant e-invoices when the expense happens, not at filing time.');
